import React from 'react';
import { ChevronDown, Menu } from 'lucide-react';

const CategoryBar = () => {
  const categories = [
    'Fresh',
    'Prime Video',
    'Sell',
    "Today's Deals",
    'Mobile',
    'New Releases',
    'Prime',
    'Amazon Pay',
    'Electronics',
    'Customer Service',
    'Home & Kitchen',
    'Fashion',
    'Computers',
    'Toys & Games'
  ];

  return (
    <div className="bg-[#232F3E] text-white shadow-sm">
      <div className="max-w-7xl mx-auto px-4">
        <div className="flex items-center h-[38px] space-x-3 overflow-x-auto scrollbar-hide">
          {/* All Menu - Highlighted with background */}
          <div className="flex items-center space-x-1 bg-white/10 hover:bg-white/20 px-3 py-1 rounded cursor-pointer whitespace-nowrap transition-colors border border-white/20">
            <Menu size={18} />
            <span className="text-sm font-bold">All</span>
          </div>

          {/* Categories - White with hover effect */}
          {categories.map((category, index) => (
            <div
              key={index}
              className="text-white/90 hover:text-white hover:bg-white/10 px-3 py-1 rounded cursor-pointer whitespace-nowrap text-sm transition-colors border border-transparent hover:border-white/20"
            >
              {category}
            </div>
          ))}

          {/* Trending arrow indicator */}
          <div className="flex items-center text-sm text-white/90 hover:text-white hover:bg-white/10 px-3 py-1 rounded cursor-pointer whitespace-nowrap transition-colors border border-transparent hover:border-white/20">
            <span>Trending</span>
            <ChevronDown size={14} className="ml-1" />
          </div>
        </div>
      </div>
    </div>
  );
};

export default CategoryBar;
